INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (135, 110, 'BOPP BOPET cigarette tear tape envelop tear strip', '../upload/image/20180929/20180929104114_15457.jpg', '<p></p><p>BOPP BOPET cigarette tear tape envelop tear strip</p> <p>BOPP/BOPET self adhesive tear tape lines were for packing/opening of cigarette packs and other packs. it was self adhesive tear tape.<br/> tear tape have BOPP tear tape, BOPET tear tape,cigarette tear tape,self adhesive tear tape,and other non cigarette usage tear tapes Various sizes for adhesive tear tape:<br/> a) Thickness of tear tape: 25-40UM b) Width of tear tape rolls: 1.6mm-6.0mm<br/> c) Length of tear tape rolls: 5,000m-70,000m<br/> 2) Printing design: a) Color printing of tear tape rolls: gold, single gold, single silver, full solid red, yellow,white,black, etc. b) Logo printing of tear tape rolls: ink printing logo, laser, holographic effect<br/> 3.) Packing for of tear tape rolls: Cartons (16rolls/carton)<br/> Certification: ISO9001, ISO14001, OHSMS18000 <br/> 4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper,envelop tear strip</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (135, 111, 'tear hair tape self adhesive tear strip', '../upload/image/20180922/20180922163905_89447.jpg', '<p></p><p>tear hair tape self adhesive tear strip</p> <p>Self adhesive tear tape (tear strip) are used for opening of cigarette packs, biscuit bag/boxes, chewing gum bags, medicine pieces, garments, CD, and so forth.<br/> Tear tapes included BOPP tear tape,BOPET tear tape,adhesive tear tape ,cigarette tear tape,BOPET tear tape and other non cigarette usage tear tapes<br/> 1) Material of Self adhesive tear tape: BOPET, BOPP,VMOPP,VMOPP. <br/> 2) Width of tear tape rolls: 1.2 - 8.0mm ( such as:1.6mm,1.8mm,2.0mm,2.5mm,3.0mm,4.5mm,6.0mm,8.0mm..)<br/> 3) Run length of tear tape rolls: 5,000 - 50,000m/spool<br/> 4) Color of tear tape rolls: red, gold, silver, green, blue, yellow, transparent, and so forth.<br/> 5) Inner packing for of tear tape rolls: using cartons. Outer packing:using pallets.<br/> 4.) others: anti-counterfeiting tear tape,lightness beam laser labels,water-transfer boardpaper,super crystal brightness cigarette tipping paper</p>', '2026-09-06 20:58:45');